import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
// ------------------------------------------------------------------
// FONT LOADER
// ------------------------------------------------------------------
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// ------------------------------------------------------------------
// SCHEMA
// ------------------------------------------------------------------


export type FloatingPromptBoxProps = Record<string, any>;

// ------------------------------------------------------------------
// ICONS
// ------------------------------------------------------------------
const PlusIcon: React.FC<{ color: string; size?: number }> = ({ color, size = 24 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <line x1="12" y1="5" x2="12" y2="19"></line>
    <line x1="5" y1="12" x2="19" y2="12"></line>
  </svg>
);

const ArrowUpIcon: React.FC<{ color: string; size?: number }> = ({ color, size = 24 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
    <line x1="12" y1="19" x2="12" y2="5"></line>
    <polyline points="5 12 12 5 19 12"></polyline>
  </svg>
);

// ------------------------------------------------------------------
// MAIN COMPONENT
// ------------------------------------------------------------------
const FloatingPromptBox: React.FC<FloatingPromptBoxProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 12,
  promptText = "You can now generate motion graphics like this using Malloy Studio.",
  boxColor = "#121212",
  highlightColor = "#ff00cf",
  textColor = "#ffffff",
  accentColor = "#ffffff",
  fontSize = 55,
  typingSpeed = 1,
  rippleStrokeWidth = 10,
  offsetX = -80,
  offsetY = 0,
}) => {
  // Load fonts
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // ----------------------------------------
  // UTILS & PARSING
  // ----------------------------------------
  const bgFinal = transparentBackground ? "transparent" : backgroundColor;
  
  // Length calculation for typing timing
  const totalLength = promptText.length;
  // Duration for typing based on speed slider (arbitrary scaling)
  // Fix: Ensure duration is at least 1 frame to prevent [15, 15] range error
  const typingDurationInFrames = Math.max(1, Math.floor((totalLength * 2) / typingSpeed)); 
  const typingStartFrame = 15; // Delay after box entry
  
  // Ripple timing
  const typingEndFrame = typingStartFrame + typingDurationInFrames;
  const rippleStartFrame = typingEndFrame + 5; // Start shortly after typing finishes
  const rippleDuration = 30;

  // ----------------------------------------
  // ANIMATIONS
  // ----------------------------------------
  
  // 1. Box Entrance (Smooth slide up + Float)
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 20, stiffness: 80, mass: 2 }, // Smoother, heavier feel for "into center" effect
  });

  // Entrance movement (Vertical slide up from bottom)
  const slideInY = interpolate(entranceSpring, [0, 1], [height * 0.3, 0]);
  
  // Floating movement (Continuous sine wave)
  const floatY = Math.sin(frame * 0.05) * 12;

  // Combine entrance, float, and user defined offset
  const currentTranslateY = slideInY + floatY + offsetY;

  const opacityBox = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" });
  
  // 3D Perspective settings
  const rotateY = interpolate(entranceSpring, [0, 1], [-25, -12]); // Starts more tilted, settles at -12
  const rotateX = interpolate(entranceSpring, [0, 1], [15, 5]); // Slightly tilted forward initially
  const scale = interpolate(entranceSpring, [0, 1], [0.9, 1]); // Subtle scale up

  // 2. Typing Progress
  const typingProgress = interpolate(
    frame,
    [typingStartFrame, typingEndFrame],
    [0, totalLength],
    { extrapolateRight: "clamp", easing: Easing.linear }
  );

  // 3. Ripple Animation
  const rippleProgress = interpolate(
    frame,
    [rippleStartFrame, rippleStartFrame + rippleDuration],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const rippleScale = interpolate(rippleProgress, [0, 1], [1, 2.2], { easing: Easing.out(Easing.ease) });
  const rippleOpacity = interpolate(rippleProgress, [0, 0.5, 1], [0.8, 0.4, 0], { extrapolateRight: "clamp" });
  const showRipple = frame >= rippleStartFrame && frame < rippleStartFrame + rippleDuration;

  // ----------------------------------------
  // RENDER HELPERS
  // ----------------------------------------
  
  // Helper to render text with typing effect
  const renderTypedText = () => {
    const visibleChars = Math.floor(typingProgress);
    const textToShow = promptText.substring(0, visibleChars);
    
    // Cursor logic (blinking)
    const isTyping = visibleChars < totalLength;
    const showCursor = isTyping && frame % 20 < 10;

    return (
      <div style={{ 
        display: "inline", 
        fontSize: fontSize, 
        lineHeight: 1.3, // Tighter line height
        letterSpacing: "-0.02em", // Tighter tracking
        fontWeight: 500,
        color: textColor,
        whiteSpace: "pre-wrap"
      }}>
        {textToShow}
        {showCursor && (
          <span style={{ 
            borderRight: `3px solid ${accentColor}`, 
            marginLeft: 2 
          }} />
        )}
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgFinal,
        fontFamily: "Inter, sans-serif",
        perspective: "1200px", // Critical for 3D effect
        display: "flex", // Ensure flex properties apply for centering
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden"
      }}
    >
      {/* Optional: Abstract background blobs to mimic "minimal blurred" feel */}
      <div style={{
        position: "absolute",
        top: height * 0.2,
        left: width * 0.2,
        width: width * 0.5,
        height: width * 0.5,
        background: `radial-gradient(circle, ${highlightColor}20 0%, transparent 70%)`,
        filter: "blur(60px)",
        transform: `translateY(${Math.sin(frame * 0.02) * 20}px)`,
      }}/>
      <div style={{
        position: "absolute",
        bottom: height * 0.1,
        right: width * 0.1,
        width: width * 0.6,
        height: width * 0.6,
        background: `radial-gradient(circle, ${accentColor}10 0%, transparent 60%)`,
        filter: "blur(80px)",
        transform: `translateY(${Math.cos(frame * 0.03) * 30}px)`,
      }}/>

      {/* 3D Tilted Box Container */}
      <div
        style={{
          width: width * 0.82, // Slightly wider to match reference proportion
          height: height * 0.45, // Changed from minHeight to height to pin layout size
          position: "relative",
          transformStyle: "preserve-3d",
          transform: `
            translateX(${offsetX}px)
            translateY(${currentTranslateY}px)
            rotateY(${rotateY}deg)
            rotateX(${rotateX}deg)
            scale(${scale})
          `,
          opacity: opacityBox,
        }}
      >
        {/* Glassmorphism Surface */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            // Replaced solid background with radial gradient + base color to match reference
            background: `radial-gradient(circle at 50% 0%, rgba(255,255,255,0.1) 0%, transparent 80%), ${boxColor}F2`,
            backdropFilter: "blur(20px)",
            borderRadius: 48, 
            border: `1px solid rgba(255,255,255,0.1)`, // Refined border
            // Updated shadow to include distinct outer glow from reference
            boxShadow: `
              0 0 50px -5px rgba(255, 255, 255, 0.15),
              0 30px 60px -12px rgba(0, 0, 0, 0.8),
              inset 0 1px 1px rgba(255, 255, 255, 0.1)
            `,
          }}
        >
          {/* Inner Content Layout */}
          <div style={{
            display: "flex",
            flexDirection: "column",
            height: "100%",
            padding: 56, // Increased padding
            justifyContent: "space-between",
          }}>
            
            {/* Top Area: Text */}
            <div style={{ 
              flex: 1, 
              display: "flex", 
              alignItems: "flex-start",
              paddingBottom: 40,
              filter: "drop-shadow(0 2px 4px rgba(0,0,0,0.5))", // Enhance text legibility
              overflow: "hidden", // Ensures text is truncated if it overflows
              width: "100%", // Ensures width is constrained
            }}>
              {renderTypedText()}
            </div>

            {/* Bottom Area: UI Controls */}
            <div style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginTop: "auto",
              flexShrink: 0, // Prevents controls from shrinking
            }}>
              
              {/* Left Controls */}
              <div style={{ display: "flex", gap: 20 }}>
                {/* Plus Button */}
                <div style={{
                  width: 80, // Updated size to match arrow button
                  height: 80, // Updated size to match arrow button
                  borderRadius: "50%",
                  backgroundColor: `${accentColor}15`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: "pointer",
                }}>
                  <PlusIcon color={accentColor} size={40} />
                </div>
              </div>

              {/* Right Controls */}
              <div style={{ display: "flex", alignItems: "center", gap: 24 }}>
                {/* Send Button */}
                <div style={{
                  width: 80, // Much larger send button
                  height: 80, // Much larger send button
                  borderRadius: "50%",
                  backgroundColor: accentColor,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  boxShadow: `0 4px 12px ${accentColor}40`,
                  position: "relative", // Ensure relative for ripple absolute positioning
                }}>
                  {showRipple && (
                    <div
                      style={{
                        position: "absolute",
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        borderRadius: "50%",
                        border: `${rippleStrokeWidth}px solid ${highlightColor}`,
                        opacity: rippleOpacity,
                        transform: `scale(${rippleScale})`,
                      }}
                    />
                  )}
                  <ArrowUpIcon color={boxColor} size={40} />
                </div>
              </div>
              
            </div>
          </div>
        </div>

        {/* Reflection Glint (Simulated) */}
        <div style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: "100%",
          background: `linear-gradient(120deg, transparent 40%, ${accentColor}08 50%, transparent 60%)`,
          borderRadius: 48,
          pointerEvents: "none",
          zIndex: 10,
        }} />
        
      </div>
    </AbsoluteFill>
  );
};

export default FloatingPromptBox;